import CryptoKit
import Foundation
import XCTest
@testable import MacScope

/// Fixtures are reduced actual full-TU JSON emitted by Xcode 27.2 clang on 2026-10-06.
/// Only loc/range/isUsed/isReferenced presentation fields were removed. Every top-level declaration,
/// executable child, attribute and type is retained; compiler IDs are normalized consistently with
/// all declaration references. Identical compiler header declarations are shared by the fixtures.
/// No AST filter was used.
/// Profile: -std=c11 -O0 -Wall -Wextra -Werror -target arm64-apple-macos27.0 -isysroot
/// selected macOS SDK -ffreestanding -fno-builtin -ferror-limit=8 -fsyntax-only -Xclang -ast-dump=json.
final class ReconstructionSourceASTAdmissionTests: XCTestCase {
    private let profile = ReconstructionSourceASTAdmission.profileID
    private let sourceHash = String(repeating: "a", count: 64)

    private func fixture(_ functions: Data) throws -> Data {
        let types = try XCTUnwrap(JSONSerialization.jsonObject(with: Self.typeDeclarations) as? [[String: Any]])
        let functions = try XCTUnwrap(JSONSerialization.jsonObject(with: functions) as? [[String: Any]])
        return try JSONSerialization.data(withJSONObject: ["kind": "TranslationUnitDecl", "inner": types + functions], options: [.sortedKeys])
    }
    private func admit(_ json: Data) throws -> ReconstructionSourceASTAdmission.Result {
        try ReconstructionSourceASTAdmission.validate(json: json, expectedSourceSHA256: sourceHash, profileID: profile)
    }
    func testActualClangTernaryAndIfLocalFormsAreAdmitted() throws {
        for functions in [Self.ternaryFunctions, Self.ifFunctions] {
            let bytes = try fixture(functions), result = try admit(bytes)
            XCTAssertEqual(result.sourceSHA256, sourceHash)
            XCTAssertEqual(result.profileID, profile)
            XCTAssertEqual(result.functionName, "reconstructed")
            XCTAssertEqual(result.astSHA256, SHA256.hash(data: bytes).map { String(format: "%02x", $0) }.joined())
            XCTAssertGreaterThan(result.nodeCount, 200)
        }
    }
    func testActualClangPrintfAndConstructorSpoofsRejectBeforeExecution() throws {
        // printf fixture: int printf(const char *s, ...) { (void)s; return 0; }
        // constructor fixture: __attribute__((constructor)) static void spoof(void) {}
        // Both also define uint32_t reconstructed(uint32_t x) { return x; }.
        for functions in [Self.printfFunctions, Self.constructorFunctions] {
            XCTAssertThrowsError(try admit(fixture(functions)))
        }
    }
    func testWholeTranslationUnitDoesNotTrustLocationsOrLineDirectives() throws {
        var object = try XCTUnwrap(JSONSerialization.jsonObject(with: fixture(Self.ternaryFunctions)) as? [String: Any])
        var inner = try XCTUnwrap(object["inner"] as? [[String: Any]])
        inner.append(["kind": "VarDecl", "id": "global", "name": "hidden", "type": ["qualType": "unsigned int"],
                      "loc": ["file": "/trusted/stdint.h", "presumedFile": "/trusted/stdint.h"]])
        object["inner"] = inner
        XCTAssertThrowsError(try admit(JSONSerialization.data(withJSONObject: object)))
    }
    func testCallsAssemblyAttributesPointersStaticAndUnknownNodesReject() throws {
        for kind in ["CallExpr", "GCCAsmStmt", "MSAsmStmt", "StmtExpr", "ArraySubscriptExpr", "MemberExpr", "WhileStmt", "MysteryExpr"] {
            var functions = try XCTUnwrap(JSONSerialization.jsonObject(with: Self.ternaryFunctions) as? [[String: Any]])
            var function = functions[0], children = try XCTUnwrap(function["inner"] as? [[String: Any]])
            children[1] = ["kind": "CompoundStmt", "inner": [["kind": kind]]]
            function["inner"] = children; functions[0] = function
            XCTAssertThrowsError(try admit(fixture(JSONSerialization.data(withJSONObject: functions))), kind)
        }
        for attribute in ["ConstructorAttr", "AliasAttr", "AsmLabelAttr", "SectionAttr"] {
            var functions = try XCTUnwrap(JSONSerialization.jsonObject(with: Self.ternaryFunctions) as? [[String: Any]])
            var children = try XCTUnwrap(functions[0]["inner"] as? [[String: Any]])
            children.append(["kind": attribute]); functions[0]["inner"] = children
            XCTAssertThrowsError(try admit(fixture(JSONSerialization.data(withJSONObject: functions))), attribute)
        }
        var functions = try XCTUnwrap(JSONSerialization.jsonObject(with: Self.ifFunctions) as? [[String: Any]])
        var children = try XCTUnwrap(functions[0]["inner"] as? [[String: Any]])
        var body = children[1], statements = try XCTUnwrap(body["inner"] as? [[String: Any]])
        var declaration = statements[0], locals = try XCTUnwrap(declaration["inner"] as? [[String: Any]])
        locals[0]["storageClass"] = "static"; declaration["inner"] = locals; statements[0] = declaration
        body["inner"] = statements; children[1] = body; functions[0]["inner"] = children
        XCTAssertThrowsError(try admit(fixture(JSONSerialization.data(withJSONObject: functions))))
    }
    func testBoundsMalformedJSONAuthorityAndDanglingReferenceReject() throws {
        let bytes = try fixture(Self.ternaryFunctions)
        XCTAssertThrowsError(try ReconstructionSourceASTAdmission.validate(json: bytes, expectedSourceSHA256: sourceHash, profileID: "other"))
        XCTAssertThrowsError(try ReconstructionSourceASTAdmission.validate(json: bytes, expectedSourceSHA256: "bad", profileID: profile))
        XCTAssertThrowsError(try admit(Data(repeating: 32, count: ReconstructionSourceASTAdmission.maximumBytes + 1)))
        XCTAssertThrowsError(try admit(Data("{\"kind\":\"TranslationUnitDecl\",\"kind\":\"TranslationUnitDecl\"}".utf8)))
        XCTAssertThrowsError(try admit(bytes.dropLast()))
        let text = try XCTUnwrap(String(data: bytes, encoding: .utf8))
        // Actual ternary parameter ID, including its declaration and references. Replace only the
        // referenced declaration IDs to prove a same-name forged reference does not gain authority.
        let functions = try XCTUnwrap(JSONSerialization.jsonObject(with: Self.ternaryFunctions) as? [[String: Any]])
        let children = try XCTUnwrap(functions[0]["inner"] as? [[String: Any]])
        let id = try XCTUnwrap(children[0]["id"] as? String)
        let forged = text.replacingOccurrences(of: "\"referencedDecl\":{\"id\":\"" + id + "\"", with: "\"referencedDecl\":{\"id\":\"missing\"")
        XCTAssertNotEqual(forged, text)
        XCTAssertThrowsError(try admit(Data(forged.utf8)))
    }
    func testNodeAndDepthWorkLimitsReject() throws {
        let returnStatement: [String: Any] = ["kind": "ReturnStmt", "inner": [["kind": "IntegerLiteral", "type": ["qualType": "unsigned int"], "value": "0"]]]
        for excessiveDepth in [false, true] {
            var functions = try XCTUnwrap(JSONSerialization.jsonObject(with: Self.ternaryFunctions) as? [[String: Any]])
            var children = try XCTUnwrap(functions[0]["inner"] as? [[String: Any]])
            var body: [String: Any] = ["kind": "CompoundStmt", "inner": [returnStatement]]
            if excessiveDepth {
                for _ in 0..<70 { body = ["kind": "CompoundStmt", "inner": [body]] }
            } else {
                body["inner"] = Array(repeating: ["kind": "NullStmt"], count: ReconstructionSourceASTAdmission.maximumNodes) + [returnStatement]
            }
            children[1] = body; functions[0]["inner"] = children
            XCTAssertThrowsError(try admit(fixture(JSONSerialization.data(withJSONObject: functions))))
        }
    }
